csp.policy.caddy:
header {
    Content-Security-Policy "default-src 'self'; script-src 'nonce-{http.vars.csp_nonce}' 'strict-dynamic' https: 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'"
}

csp.unsafe-inline.nginx:
# 1. Generate a nonce per request and place it on every <script> tag.
# 2. Then drop 'unsafe-inline' (keep it only as the CSP1 fallback shown here):
add_header Content-Security-Policy "script-src 'nonce-$csp_nonce' 'strict-dynamic' https: 'unsafe-inline'; object-src 'none'; base-uri 'none'" always;

csp.wildcard.nginx:
add_header Content-Security-Policy "script-src 'self' https://cdn.example.com; object-src 'none'; base-uri 'none'" always;
# Better: stop depending on the host allowlist entirely
# add_header Content-Security-Policy "script-src 'nonce-$csp_nonce' 'strict-dynamic'" always;

csp.reporting.caddy:
header {
    Reporting-Endpoints `csp-endpoint="https://example.com/csp-reports"`
    Content-Security-Policy "...; report-to csp-endpoint; report-uri https://example.com/csp-reports"
}

cors.nginx:
map $http_origin $cors_origin {
    default                       "";
    "https://app.example.com"     $http_origin;
    "https://admin.example.com"   $http_origin;
}
location /api/ {
    add_header Access-Control-Allow-Origin  $cors_origin always;
    add_header Access-Control-Allow-Credentials "true" always;
    add_header Vary "Origin" always;
}

cors.caddy:
@allowed_origin header Origin "https://app.example.com"
header @allowed_origin {
    Access-Control-Allow-Origin "https://app.example.com"
    Access-Control-Allow-Credentials "true"
    Vary "Origin"
}

