tls.versions.caddy:
tls {
    protocols tls1.2 tls1.3
}
# Caddy defaults to TLS 1.2+ already; this block is only needed to pin it.

tls.ciphers.nginx:
ssl_protocols TLSv1.2 TLSv1.3;
ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305;
ssl_prefer_server_ciphers on;
ssl_ecdh_curve X25519:prime256v1:secp384r1;

tls.ciphers.caddy:
tls {
    ciphers TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256 TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256 TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305 TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305
    curves x25519 secp256r1 secp384r1
}

tls.certificate.nginx:
ssl_certificate     /etc/letsencrypt/live/example.com/fullchain.pem;   # leaf + intermediates
ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;
# fullchain.pem, not cert.pem: cert.pem alone leaves the chain incomplete.

tls.certificate.caddy:
# Caddy obtains and renews certificates automatically:
example.com {
    # nothing to configure; or, for your own certificate:
    # tls /etc/ssl/fullchain.pem /etc/ssl/privkey.pem
}

tls.ocsp.nginx:
ssl_stapling on;
ssl_stapling_verify on;
ssl_trusted_certificate /etc/letsencrypt/live/example.com/chain.pem;
resolver 1.1.1.1 9.9.9.9 valid=300s;

tls.extras.nginx:
listen 443 ssl;
http2 on;
ssl_session_cache shared:SSL:10m;
ssl_session_timeout 1d;
ssl_session_tickets off;   # keeps forward secrecy simple

tls.extras.caddy:
# Caddy enables HTTP/2 and h3 by default and never enables TLS compression.
servers {
    protocols h1 h2 h3
}

redirect.nginx:
server {
    listen 80;
    listen [::]:80;
    server_name example.com www.example.com;
    return 301 https://$host$request_uri;
}

redirect.caddy:
# Caddy redirects HTTP to HTTPS automatically for any site with a hostname.
example.com {
    # automatic HTTP -> HTTPS redirect
}

security-txt.nginx:
location = /.well-known/security.txt {
    default_type text/plain;
    return 200 "Contact: mailto:security@example.com
Expires: 2027-01-01T00:00:00.000Z
Preferred-Languages: en, es
Canonical: https://example.com/.well-known/security.txt
";
}

security-txt.caddy:
handle /.well-known/security.txt {
    header Content-Type text/plain
    respond "Contact: mailto:security@example.com\nExpires: 2027-01-01T00:00:00.000Z\n" 200
}

http-methods.nginx:
# nginx never implements TRACE, but a proxied backend might:
if ($request_method !~ ^(GET|HEAD|POST|PUT|PATCH|DELETE|OPTIONS)$) {
    return 405;
}

info-headers.nginx:
server_tokens off;
# For headers added by a proxied backend:
proxy_hide_header X-Powered-By;
proxy_hide_header X-AspNet-Version;
proxy_hide_header X-AspNetMvc-Version;
proxy_hide_header X-Generator;
# Removing the Server header entirely needs the headers-more module:
#   more_clear_headers 'Server';

legacy-headers.nginx:
# nginx: simply stop emitting them. To strip them from a backend:
proxy_hide_header X-XSS-Protection;
proxy_hide_header Public-Key-Pins;
proxy_hide_header Public-Key-Pins-Report-Only;
proxy_hide_header Expect-CT;
